    examples: [{"input":"arr = [5, 1, 4, 2]","output":"[1, 2, 4, 5]","note":"Lượt 1 đẩy 5 về cuối: [1,4,2,5]. Lượt 2: [1,2,4,5]. Lượt 3 không đổi chỗ lần nào nên cờ swapped = false và dừng sớm."},{"input":"arr = [1, 2, 3, 4]","output":"[1, 2, 3, 4]","note":"Mảng đã sắp: chỉ một lượt duyệt không đổi chỗ rồi dừng — O(n). Đây là ưu điểm duy nhất của bubble sort so với selection sort."}],
    diff: "Dễ",
    trap: "Không bao giờ dùng trong code thật. Điểm cộng khi phỏng vấn: nói được nó ỔN ĐỊNH (stable) và đạt O(n) khi mảng gần như đã sắp xếp nhờ cờ swapped dừng sớm.",
    alt: {"title":"Cách khác — Cocktail Shaker Sort (nổi bọt hai chiều)","complexity":"O(n²) nhưng nhanh hơn thực nghiệm","note":"Bubble Sort xử lý rất tệ 'rùa' — phần tử NHỎ nằm gần cuối mảng, mỗi lượt chỉ nhích lên 1 ô. Quét xuôi rồi quét ngược sẽ giải quyết được.","java":"void cocktailSort(int[] a) {\n    int start = 0, end = a.length - 1;\n    boolean swapped = true;\n    while (swapped) {\n        swapped = false;\n        for (int i = start; i < end; i++)            // xuôi: đẩy số lớn về cuối\n            if (a[i] > a[i + 1]) { swap(a, i, i + 1); swapped = true; }\n        if (!swapped) break;\n        end--;\n\n        swapped = false;\n        for (int i = end - 1; i >= start; i--)       // ngược: kéo số nhỏ về đầu\n            if (a[i] > a[i + 1]) { swap(a, i, i + 1); swapped = true; }\n        start++;\n    }\n}\n\nprivate void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }"},
    complexity: "Thời gian: O(n²) · Bộ nhớ: O(1) · Ổn định (stable)",
    idea: "Lặp qua mảng nhiều lượt, mỗi lượt so sánh từng CẶP KỀ NHAU và hoán đổi nếu sai thứ tự — phần tử lớn nhất 'nổi' dần về cuối. Dễ hiểu nhất, hay bị hỏi để kiểm tra tư duy cơ bản.",
    steps: ["Lượt i: duyệt j từ 0 đến n-2-i.", "Nếu arr[j] > arr[j+1] → hoán đổi.", "Sau lượt i, phần tử lớn thứ i đã đứng đúng chỗ cuối mảng.", "Tối ưu: nếu một lượt không có hoán đổi nào → mảng đã sắp xếp, dừng sớm."],
    java: "void bubbleSort(int[] arr) {\n    int n = arr.length;\n    for (int i = 0; i < n - 1; i++) {\n        boolean swapped = false;\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int tmp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = tmp;\n                swapped = true;\n            }\n        }\n        if (!swapped) break; // đã sắp xếp xong\n    }\n}",
    js: "function bubbleSort(arr) {\n  const n = arr.length;\n  for (let i = 0; i < n - 1; i++) {\n    let swapped = false;\n    for (let j = 0; j < n - 1 - i; j++) {\n      if (arr[j] > arr[j + 1]) {\n        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];\n        swapped = true;\n      }\n    }\n    if (!swapped) break;\n  }\n  return arr;\n}"
