    java: "void fizzBuzz(int n) {\n    for (int i = 1; i <= n; i++) {\n        String s = \"\";\n        if (i % 3 == 0) s += \"Fizz\";\n        if (i % 5 == 0) s += \"Buzz\";\n        System.out.println(s.isEmpty() ? String.valueOf(i) : s);\n    }\n}",
