    alt: {"title":"Cách khác — kiểm tra SỐ có đối xứng không, không đổi sang chuỗi (LC 9)","complexity":"O(số chữ số) thời gian · O(1) bộ nhớ","note":"Chỉ đảo NỬA SAU của số rồi so sánh với nửa đầu, nhờ vậy không bao giờ bị tràn int. Số âm luôn không đối xứng vì có dấu trừ ở đầu.","java":"boolean isPalindromeNumber(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) return false;   // số âm, hoặc kết thúc bằng 0\n    int reversedHalf = 0;\n    while (x > reversedHalf) {\n        reversedHalf = reversedHalf * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversedHalf || x == reversedHalf / 10;   // độ dài chẵn hoặc lẻ\n}"},
